import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    my_c = 0
    op_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    for a in op:
        if a == 'C':
            op_c += 1

    last_me = me[-1]
    last_op = op[-1]

    # Endgame: exploit a proven cooperator, otherwise defect safely.
    if n >= 97:
        if op_c >= n - 3:
            return 'D'
        return 'D' if op_c <= n // 2 else ('D' if rng.random() < 0.5 else 'C')

    # Opponent essentially always cooperated: milk it near the end, else keep CC.
    if op_c == n:
        if n >= 80:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'C'

    # Opponent heavily defective: defend, but probe occasionally for recovery.
    if op_c * 3 <= n:
        if last_op == 'C':
            # Reward genuine switches back toward cooperation.
            if op_c >= 3 and rng.random() < 0.7:
                return 'C'
            return 'D'
        if last_me == 'D' and last_op == 'D' and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: reciprocate with strong forgiveness.
    if op_c * 10 >= n * 9:
        if last_op == 'D':
            return 'D'
        if last_me == 'D' and rng.random() < 0.9:
            return 'C'
        return 'C'

    # Main regime: forgiving tit-for-tat with anti-death-spiral resets.
    if last_op == 'D':
        if last_me == 'D':
            # Break mutual defection loops, more eagerly if opponent usually cooperates.
            if op_c * 2 >= n:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Opponent defected while we cooperated: retaliate, occasional forgiveness.
        if op_c * 4 >= n * 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if last_me == 'D':
        # Return to cooperation to repair trust after our defection.
        return 'C'
    # Small probing against mid-range opponents to find exploitables.
    if op_c * 2 < n and rng.random() < 0.06:
        return 'D'
    return 'C'
